#include <iostream>
#include <string>
#include <cctype>

// Recursive helper for counting lowercase letters
int getNumberOfLowercaseLetters(const std::string& s, int low) {
    if (low >= static_cast<int>(s.length())) {
        return 0; // Base case: end of string
    }
    int countCurrent = std::islower(static_cast<unsigned char>(s[low])) ? 1 : 0;
    return countCurrent + getNumberOfLowercaseLetters(s, low + 1);
}

// Public wrapper
int getNumberOfLowercaseLetters(const std::string& s) {
    return getNumberOfLowercaseLetters(s, 0);
}

// Recursive helper to display string in reverse using high index
void reverseDisplay(const std::string& s, int high) {
    if (high < 0) {
        return; // Base case: reached before start
    }
    std::cout << s[high];
    reverseDisplay(s, high - 1);
}

// Public wrapper for reverseDisplay
void reverseDisplay(const std::string& s) {
    reverseDisplay(s, static_cast<int>(s.length()) - 1);
}

int main() {
    std::string text = "Hello World 2026";
    std::cout << "Original: " << text << "\n";
    std::cout << "Lowercase count: " << getNumberOfLowercaseLetters(text) << "\n";
    std::cout << "Reversed: ";
    reverseDisplay(text);
    std::cout << "\n";
    return 0;
}

#include <iostream>
#include <string>

// Recursive helper function for permutations
void displayPermutation(const std::string& s1, const std::string& s2, int& count) {
    if (s2.empty()) {
        std::cout << s1 << "\n";
        ++count;
        return;
    }
    for (std::size_t i = 0; i < s2.length(); ++i) {
        // Pick s2[i] and append to s1, remove from s2
        std::string newS1 = s1 + s2[i];
        std::string newS2 = s2.substr(0, i) + s2.substr(i + 1);
        displayPermutation(newS1, newS2, count);
    }
}

// Public driver function
void displayPermutation(const std::string& s) {
    int totalPerms = 0;
    displayPermutation("", s, totalPerms);
    std::cout << "Total permutations: " << totalPerms << "\n";
}

int main() {
    std::string letters = "abc";
    displayPermutation(letters);
    return 0;
}

#include <iostream>
#include <string>
#include <cctype>

// Recursive decimal to binary
std::string decimalToBinary(int value) {
    if (value == 0) {
        return "0";
    }
    if (value == 1) {
        return "1";
    }
    return decimalToBinary(value / 2) + std::to_string(value % 2);
}

// Recursive decimal to hex
std::string decimalToHex(int value) {
    if (value == 0) {
        return "0";
    }
    const char hexDigits[] = "0123456789ABCDEF";
    if (value < 16) {
        return std::string(1, hexDigits[value]);
    }
    return decimalToHex(value / 16) + hexDigits[value % 16];
}

// Helper for hexToDecimal: Horner's method accumulating from left to right
int hexToDecimalHelper(const std::string& hexString, int index, int currentVal) {
    if (index >= static_cast<int>(hexString.length())) {
        return currentVal;
    }
    char c = hexString[index];
    int digit = 0;
    if (c >= '0' && c <= '9') digit = c - '0';
    else if (c >= 'A' && c <= 'F') digit = 10 + (c - 'A');
    else if (c >= 'a' && c <= 'f') digit = 10 + (c - 'a');
    return hexToDecimalHelper(hexString, index + 1, currentVal * 16 + digit);
}

int hexToDecimal(const std::string& hexString) {
    return hexToDecimalHelper(hexString, 0, 0);
}

int main() {
    int dec = 171;
    std::string bin = decimalToBinary(dec);
    std::string hex = decimalToHex(dec);
    std::cout << dec << " in binary: " << bin << "\n";
    std::cout << dec << " in hex: " << hex << "\n";
    std::cout << hex << " back to decimal: " << hexToDecimal(hex) << "\n";
    return 0;
}
